insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'english_proficiency', 'English Proficiency Exam scores: Required of all international applicants unless 1) your native language is English or 2) English is the primary language of instruction in your secondary school. For n', 'English Proficiency Exam scores: Required of all international applicants unless 1) your native language is English or 2) English is the primary language of instruction in your secondary school. For non-Native English speakers where English is the primary language of instruction in your secondary school, Caltech strongly recommends an English Proficiency Exam score. We accept the Duolingo English Test (DET), IELTS, or the TOEFL.', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/application-requirements', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0013', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'international_requirement', 'Caltech is need-aware for international applicants because the total amount of financial aid funds is limited for these students, and we remain committed to meeting the demonstrated need of all admitt', 'Caltech is need-aware for international applicants because the total amount of financial aid funds is limited for these students, and we remain committed to meeting the demonstrated need of all admitted students.', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/application-requirements', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0014', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'international_requirement', 'Translation of documents: All application materials must be submitted in English. If they were originally printed in a language other than English, we require the original document and an English tran', 'Translation of documents: All application materials must be submitted in English. If they were originally printed in a language other than English, we require the original document and an English translation. We will not review your application if any part is not translated in English.', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/application-requirements', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0015', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'supplemental_requirement', 'Upon admission, Caltech reserves the right to conduct verifications of submitted proofs. Any discrepancies or falsifications will result in the rescission of your admission to Caltech.', 'Upon admission, Caltech reserves the right to conduct verifications of submitted proofs. Any discrepancies or falsifications will result in the rescission of your admission to Caltech.', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/application-requirements', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0016', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'curriculum', 'If a student is unable to take a calculus, chemistry, and/or physics course in high school because it is not available to them or they experience unresolvable course conflicts, Caltech will accept exa', 'If a student is unable to take a calculus, chemistry, and/or physics course in high school because it is not available to them or they experience unresolvable course conflicts, Caltech will accept examination scores or the course challenge through Schoolhouse.world showing evidence of knowledge in the subject in lieu of an academic course requirement, provided both the student and their counselor document the underlying unresolvable issue(s).', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/academic-requirements-for-first-year-applicants', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0018', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'curriculum', 'A score of 5 on AP exams in AP Calculus AB, AP Calculus BC, AP Chemistry, AP Physics 1, AP Physics 2, or AP Physics C. The AP exam must be taken by application deadline. A score of 6 or 7 on the IB Ma', 'A score of 5 on AP exams in AP Calculus AB, AP Calculus BC, AP Chemistry, AP Physics 1, AP Physics 2, or AP Physics C. The AP exam must be taken by application deadline. A score of 6 or 7 on the IB Mathematics HL; Chemistry SL or HL; or Physics SL or HL examinations. The IB exam must be taken by application deadline. Completing the course challenge from Schoolhouse.world in one of the following courses: AP/College Calculus BC; AP/College Chemistry; AP/College Physics 1. Proof of certification from Schoolhouse.world is required within one week of the application deadline.', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/academic-requirements-for-first-year-applicants', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0019', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'standardized_test', 'Caltech requires first-year applicants to submit either the SAT or the ACT for admissions to Caltech. For fall 2027 applicants, Caltech does not require the ACT writing or science subscores. In fairne', 'Caltech requires first-year applicants to submit either the SAT or the ACT for admissions to Caltech. For fall 2027 applicants, Caltech does not require the ACT writing or science subscores. In fairness, Caltech will not consider a student''s composite score and instead, Caltech will consider each individual subscore: Math, English, Reading, Science (optional), and Writing (optional).', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/standardized-tests', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0020', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'standardized_test', 'SAT (Math or Reading & Writing): Bucket A 780-800, Bucket B 750-770, Bucket C Below 750. ACT (Individual subscore): Bucket A 35-36, Bucket B 33-34, Bucket C Below 33. If your score falls in Bucket A o', 'SAT (Math or Reading & Writing): Bucket A 780-800, Bucket B 750-770, Bucket C Below 750. ACT (Individual subscore): Bucket A 35-36, Bucket B 33-34, Bucket C Below 33. If your score falls in Bucket A or B, the admissions committee will not see whether you scored a 750 or 800 SAT (33-36 ACT), they will just know you''re in a range. If your score falls below a 750 SAT or 33 ACT (Bucket C), the individual exam score will be shown to admissions committee.', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/standardized-tests', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0021', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'essay', 'If you had to choose an area of interest or two today, what would you choose? Why did you choose your proposed area of interest? If you selected ''other'', what topics are you interested in pursuing? (M', 'If you had to choose an area of interest or two today, what would you choose? Why did you choose your proposed area of interest? If you selected ''other'', what topics are you interested in pursuing? (Min: 150 / Max: 200 words)', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/supplemental-application-essays', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0022', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'essay', 'Scholarly Character: How do you learn when there is no easy answer? Choose one of the following prompts: (Max: 200 words) Option 1 -- COLLABORATION: STEM as shared learning; or Option 2 -- PROCESS: Th', 'Scholarly Character: How do you learn when there is no easy answer? Choose one of the following prompts: (Max: 200 words) Option 1 -- COLLABORATION: STEM as shared learning; or Option 2 -- PROCESS: The thought behind the outcome.', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/supplemental-application-essays', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0023', 'fresh');
insert into university_requirements (university_id, requirement_type, title, requirement_detail, is_required, scope, data_confidence, verification_state, source_url, retrieved_at, is_exclusion, research_record_id, data_status) values
  ('d6fe8e8f-749f-462d-88b3-b22dfdc11a4c', 'essay', 'Scientific Drive: How does STEM come alive in your life through learning, pursuing, or making? Choose two of the following prompts: (Two Essays, Max: 200 words each) Option 1 -- LEARNING: STEM as a ne', 'Scientific Drive: How does STEM come alive in your life through learning, pursuing, or making? Choose two of the following prompts: (Two Essays, Max: 200 words each) Option 1 -- LEARNING: STEM as a never-ending rabbit hole; Option 2 -- PURSUING: STEM as sustained intellectual engagement; Option 3 -- MAKING: STEM as creation.', true, 'first_year_undergraduate', 'high', 'verified_current', 'https://www.admissions.caltech.edu/apply/first-year-applicants/supplemental-application-essays', '2026-09-01'::timestamptz, false, 'REQ-2026-09-01-CAL0024', 'fresh');
